@startuml
class Customer {
  +name : string
  +address : string
}

class Account {
  +balance : double
}

class SavingsAccount extends Account {
  +interestRate : float
}

class InvestmentAccount extends Account {
}

class Stock {
  +ticker : string
}

class StockOrder {
  +quantity : int
  +price : double
  +commission : double
}

Customer "1" -- "*" Account : owns
InvestmentAccount "1" -- "*" StockOrder : executes
StockOrder "*" -- "1" Stock : involves
StockOrder "1" -- "1" InvestmentAccount : belongs to
@enduml

